import math


def fit(rows, weights):
    try:
        if len(rows) != len(weights):
            raise ValueError('weights')
        checked_weights = []
        for weight in weights:
            if not math.isfinite(weight) or weight < 0:
                raise ValueError('weights')
            checked_weights.append(weight)
    except (TypeError, OverflowError):
        raise ValueError('weights')

    width = len(rows[0]) if rows else 0
    state = []
    for column in range(width):
        observed = [
            (row[column], weight)
            for row, weight in zip(rows, checked_weights)
            if row[column] is not None and weight > 0
        ]
        total = sum(weight for _, weight in observed)
        if total == 0:
            state.append([0.0, 1.0])
            continue

        mean = sum(value * weight for value, weight in observed) / total
        variance = sum(weight * (value - mean) ** 2 for value, weight in observed) / total
        scale = math.sqrt(variance) if variance > 0 else 1.0
        state.append([mean, scale])
    return state


def transform(rows, state):
    return [
        [None if value is None else (value - state[column][0]) / state[column][1]
         for column, value in enumerate(row)]
        for row in rows
    ]

from core import fit, transform


def solve(payload):
    train = payload['train']
    other = payload['other']
    state = fit(train, payload['weights'])
    if not train and other:
        width = len(other[0])
        state = [[0.0, 1.0] for _ in range(width)]
    return transform(other, state)
